-- Phase 7: "deep learning mode".
--  1. Reset every skill to 0 (start from absolute zero) and clear the skill history that described the old levels.
--  2. Long-form reading + graded hands-on submissions live on daily_tasks.
--  3. Briefings/themes generated by earlier versions have a different payload shape (no chapter, no rubric): they are
--     deleted so the API never has to serve a half-compatible row. They are regenerable: run `generate-weekly`/`generate-daily`.
-- Destructive by design; run once. (A later reset: `python -m app.cli reset-progress --yes`.)
set search_path = public, extensions;

update public.skills set level = 0, updated_at = now();
delete from public.skill_history;
delete from public.daily_briefings;   -- cascades to daily_tasks
delete from public.weekly_themes;

alter table public.daily_tasks add column reading_content        text;                      -- the chapter (markdown), reading tasks
alter table public.daily_tasks add column evaluation_rubric      jsonb;                     -- {pass_score, criteria:[{name, description, max_points, must_pass}]}, hands_on tasks
alter table public.daily_tasks add column user_submission        text;                      -- latest submission
alter table public.daily_tasks add column ai_evaluation_feedback text;                      -- latest feedback (markdown)
-- structured result of the latest evaluation, so the UI can render the grade breakdown
alter table public.daily_tasks add column evaluation_result      jsonb;
alter table public.daily_tasks add column evaluation_score       int check (evaluation_score between 1 and 10);
alter table public.daily_tasks add column evaluation_passed      boolean;
alter table public.daily_tasks add column attempt_count          int not null default 0;     -- evaluations used (capped by MAX_SUBMISSION_ATTEMPTS)
alter table public.daily_tasks add column submitted_at           timestamptz;
alter table public.daily_tasks add column evaluated_at           timestamptz;
